CREATE DATABASE IF NOT EXISTS edumanage; USE edumanage;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password_hash CHAR(64) NOT NULL, full_name VARCHAR(100));
CREATE TABLE departments(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, head VARCHAR(100));
CREATE TABLE teachers(id INT AUTO_INCREMENT PRIMARY KEY, teacher_code VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(100), phone VARCHAR(15), department_id INT, qualification VARCHAR(100), joining_date DATE, status VARCHAR(10) DEFAULT 'Active', FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE courses(id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, department_id INT, duration VARCHAR(30), semesters INT, credits INT, FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY, student_code VARCHAR(20) UNIQUE NOT NULL, full_name VARCHAR(100) NOT NULL, gender VARCHAR(10), dob DATE, email VARCHAR(100), phone VARCHAR(15), address VARCHAR(255), department_id INT NOT NULL, semester INT, status VARCHAR(10) DEFAULT 'Active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE attendance(id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, course_id INT NOT NULL, att_date DATE NOT NULL, status VARCHAR(10) NOT NULL, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE TABLE marks(id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, subject VARCHAR(100), semester INT, internal_marks INT, external_marks INT, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE fees(id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, semester INT, total_fees DECIMAL(10,2), paid_amount DECIMAL(10,2), payment_date DATE, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
